pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Maker maker;
    MockToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new Maker();
        token = new MockToken();
    }

    function testFuzz_property(uint256 duration, uint256 warpTime, bool isCall) public {
        duration = bound(duration, 1, 10_000 days - 1);
        warpTime = bound(warpTime, 1, 2_000_000_000);
        vm.warp(warpTime);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: isCall,
            isLong: false,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: warpTime + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(65);

        vm.prank(address(0xb0b));
        uint256[] memory noFloors = new uint256[](0);
        c.fillOrder(order, sig, noFloors);

        bytes32 orderHash = c.hashOrder(order);

        // General rule: a short order never records an expiration under the
        // maker's order hash; that key stays zero after fillOrder.
        assertTrue(c.positionExpirations(uint256(orderHash)) == 0);
    }
}

